def hook(ctx, nb):
    try:
        if ctx['action']['tool'] != 'click_action':
            return None
        val = ctx['action']['value_normalized']
    except Exception:
        return None
    if val != 'buy now':
        return None
    try:
        over_budget = ctx['predicates']['product_price_over_budget']
        missing_options = ctx['predicates']['required_options_unselected']
    except Exception:
        over_budget = False
        missing_options = False
    if over_budget:
        return {'kind': 'block_and_prompt', 'message': 'Do not buy this item because its current price is over the stated budget. Go back to search results or use Back to Search and choose an in-budget product.'}
    if missing_options:
        return {'kind': 'block_and_prompt', 'message': 'Do not buy yet. A required product option from the instruction is still unselected on this page, such as color, size, material, flavor, scent, or pack count. Choose the matching visible option first; if no option matches, use Back to Search instead of buying.'}
    return None
